function isLegacySiege(){return state?.mode==='legacy_siege'||state?.mode==='siege'}
function siegeIIModeState(){if(!isSiegeModeII())return null;state.siegeII=state.siegeII||{schema:'siege2_v1',phase:'combat',phaseLabel:'Defending Shantium',createdVersion:VERSION,briefingSeen:false,modernization:{}};state.siegeII.modernization={combat:false,forces:false,battlefield:false,economy:false,recovery:false,politics:false,outcomes:false,...(state.siegeII.modernization||{})};return state.siegeII}
