// Supersede Battlefield II command presentation while preserving all prior battlefield and army actions.
renderSiegeIICommand=function(){
 if(!state)return renderMenu();const S=siegeIICombatState(),F=siegeIIForcesState(),B=siegeIIBattlefieldState(),L=siegeIILogisticsState();checkLevel();siegeIISyncBreachIncidents(B);const ratio=S.pressure>=75?'Critical':S.pressure>=50?'Heavy':S.pressure>=25?'Rising':'Contained',D=siegeIIForceTotal(F.defenders,'defender'),A=siegeIIForceTotal(F.attackers,'attacker'),active=B.incidents.filter(x=>x.status==='active'),canBattle=B.commandActionAssault!==S.assault,canLog=L.commandActionAssault!==S.assault;
 document.getElementById('app').innerHTML=`<div class="app-shell siege2-shell"><div class="titlebar"><div class="left">${esc(state.name)} • Level ${state.level} • ${fmt(state.gold)} gold</div><div>SIEGE MODE II</div><div class="right"><span>Logistics II</span><button id="menuBtn">Menu</button></div></div><div class="game-grid siege2-foundation-grid"><div class="sidebar"><div class="panel">${guardianPanel()}</div><div class="panel"><h3>Command</h3><div class="stat-row"><span>Next assault</span><b>${S.assault}</b></div><div class="stat-row"><span>Position</span><b>${esc(siegeIICurrentPosition(B).short)}</b></div><div class="stat-row"><span>Siege pressure</span><b>${S.pressure}/100 • ${ratio}</b></div><div class="stat-row"><span>Defender morale</span><b>${S.defenderMorale}/100</b></div><div class="stat-row"><span>Logistics readiness</span><b>${siegeIILogisticsReadiness(L)}%</b></div><div class="stat-row"><span>Defenders</span><b>${D}</b></div><div class="stat-row"><span>Besiegers</span><b>${A}</b></div><div class="choice-list"><button id="siege2Assault">Begin Assault ${S.assault}</button><button id="siege2Logistics">Economy & Logistics${canLog?' • ORDER AVAILABLE':''}</button><button id="siege2Battlefield">Battlefield Situation${canBattle&&active.length?' • ACTION AVAILABLE':''}</button><button id="siege2Forces">Forces & Army Roster</button>${(state.guardian.classChoicePending||state.attributePoints||state.skillPoints)?'<button id="siegeIILevelUp">Level Up / Advancement</button>':''}<button id="siegeIIInventory">Inventory / Equipment</button><button id="siegeIIParty">Party / Roster</button><button id="siegeIIBriefing">Command Briefing</button></div></div></div><div class="panel siege2-command-panel"><h2>Siege Economy & Logistics II</h2><div class="notice"><b>The defense now consumes real stores to keep fighting.</b><br>Food, medicine, repair materials, arms/equipment, rationing, workshop capacity, captured stores, and shortages persist from assault to assault and directly affect combat readiness.</div>${siegeIILogisticsSummaryHTML(L)}${sieIILogisticsAlertHTML(L)}${sieIIBattlefieldAlertHTML(B)}<h3>Living Battlefield</h3>${sieIIBattlefieldSummaryHTML(B)}${sieIIDistrictsHTML(B)}<h3>Persistent Armies</h3>${sieIIForceSummaryHTML(F)}<h3>Recent Battle Record</h3>${sieIIHistoryHTML(S)}<div class="notice compact"><b>Integration:</b> battlefield repairs consume Materials; low Arms weakens opening support; depleted Materials expose the line; Food shortages hurt morale; Medicine determines how efficiently strategic wounded return to duty.</div></div><div class="sidebar"><div class="panel"><h3>Modernization Status</h3><div class="stat-row"><span>Architecture</span><b>Ready</b></div><div class="stat-row"><span>Combat II</span><b>Active</b></div><div class="stat-row"><span>Forces II</span><b>Active</b></div><div class="stat-row"><span>Battlefield II</span><b>Active</b></div><div class="stat-row"><span>Logistics II</span><b>Active</b></div><div class="stat-row"><span>Recovery II</span><b>Next</b></div></div><div class="panel"><h3>Supply Doctrine</h3><p class="compact">Each assault automatically consumes stores. The Guardian can issue one separate logistics order and one battlefield response between assaults; shortages continue until stocks are restored.</p></div></div><div class="panel log-panel"><h3>Command Log</h3><div class="log">${state.log.slice(-50).map(x=>`<div class="log-line ${x.type}">${esc(x.msg)}</div>`).join('')}</div></div></div></div>`;
 $('#menuBtn').onclick=gameMenu;$('#siege2Assault').onclick=siegeIIStartAssault;$('#siege2Logistics').onclick=showSiegeIILogistics;$('#siege2Battlefield').onclick=showSiegeIIBattlefield;$('#siege2Forces').onclick=showSiegeIIForces;if($('#siegeIILevelUp'))$('#siegeIILevelUp').onclick=showLevelUpPrompt;$('#siegeIIInventory').onclick=showInventory;$('#siegeIIParty').onclick=showParty;$('#siegeIIBriefing').onclick=showSiegeIIBriefing;save()
};
renderSiegeIIFoundation=renderSiegeIICommand;

// v1.6.14 — Siege Recovery & Downtime II
// Adds a siege-specific between-assault recovery window without altering Legacy Siege.
function siegeIIRecoveryState(){
 const S=siegeIICombatState();
 if(!S.recoveryII||typeof S.recoveryII!=='object')S.recoveryII={version:1,actionAssault:0,history:[],preparedAssault:0,trainedAssault:0,totalTreatments:0,totalRests:0,totalDefendersReturned:0};
 const R=S.recoveryII;R.version=1;R.history=Array.isArray(R.history)?R.history:[];R.actionAssault=Number(R.actionAssault)||0;R.preparedAssault=Number(R.preparedAssault)||0;R.trainedAssault=Number(R.trainedAssault)||0;S.modernization={...(S.modernization||{}),recovery:true};return R
}
function siegeIIRecoveryOwners(activeOnly=true){return [state.guardian,...partyMembers(activeOnly)]}
function siegeIIHealerCompanion(){return partyMembers(true).find(m=>['healer','field_mender'].includes(m.id)||allyDef(m.id)?.className==='Healer')||null}
function siegeIIHealerCapacity(){
 const L=siegeIILogisticsState(),pct=siegeIIStockPct(L,'medicine'),healer=siegeIIHealerCompanion();let q=pct>=70?4:pct>=40?3:pct>=18?2:1;if(healer)q++;const current=siegeIICombatState().assault;if((L.history||[]).some(x=>x.assault===current&&x.kind==='command-order'&&/field hospitals/i.test(x.text||'')))q++;return clamp(q,1,5)
}
function siegeIIRecoveryStatus(){
 const owners=siegeIIRecoveryOwners(true),injuries=owners.reduce((n,o)=>n+activeCombatInjuries(o).length,0),serious=owners.reduce((n,o)=>n+activeCombatInjuries(o).filter(x=>x.type==='serious').length,0),down=owners.filter(o=>o.hp<=0).length;let hp=0,hpMax=0,sta=0,staMax=0;for(const o of owners){const g=o===state.guardian,mh=g?maxHP():allyMaxHP(o),ms=g?maxStamina():allyMaxStamina(o);hp+=Math.max(0,o.hp||0);hpMax+=mh;sta+=Math.max(0,o.stamina||0);staMax+=ms}return {owners,injuries,serious,down,hpPct:hpMax?Math.round(hp/hpMax*100):100,staPct:staMax?Math.round(sta/staMax*100):100}
}
function siegeIIRecoveryMedicineCost(){const S=siegeIIRecoveryStatus(),q=siegeIIHealerCapacity();return clamp(4+S.injuries+S.serious*2-Math.max(0,q-3),4,18)}
function siegeIIRecoveryRecord(kind,text,tone='info'){const S=siegeIICombatState(),R=siegeIIRecoveryState();R.history.unshift({assault:S.assault,kind,text,tone});R.history=R.history.slice(0,50);log(`Siege II recovery: ${text}`,tone);return text}
function siegeIIRecoveryActionUsed(){return siegeIIRecoveryState().actionAssault===siegeIICombatState().assault}
function siegeIIRecoveryConsumeAction(){siegeIIRecoveryState().actionAssault=siegeIICombatState().assault}
function siegeIIRestoreActive(hpFrac,staFrac=hpFrac){for(const o of siegeIIRecoveryOwners(true))recoveryRestoreOwner(o,hpFrac,staFrac)}
function siegeIIRestAction(){
 if(siegeIIRecoveryActionUsed())return showSiegeIIRecovery();const R=siegeIIRecoveryState();siegeIIRestoreActive(.8,.95);for(const o of siegeIIRecoveryOwners(true))for(const x of ensureCombatInjuries(o))if(x.type==='bruised')x.untilDay=Math.max(combatDay()-1,(x.untilDay||combatDay())-1);for(const m of partyMembers(true))SOSServices.companions.adjustTrust(m.id,1);R.totalRests++;siegeIIRecoveryConsumeAction();const text='The active Player Party takes protected rest behind the line. HP and stamina recover substantially, while minor bruising is given time to settle.';siegeIIRecoveryRecord('rest',text,'good');save();actionResult('Protected Rest',text,'good',showSiegeIIRecovery)
}
function siegeIITreatmentAction(){
 if(siegeIIRecoveryActionUsed())return showSiegeIIRecovery();const condition=siegeIIRecoveryStatus();if(!condition.injuries&&condition.hpPct>=100&&condition.staPct>=100)return actionResult('No Treatment Needed','The active Player Party is already at full condition and has no persistent injuries.','info',showSiegeIIRecovery);const L=siegeIILogisticsState(),cost=siegeIIRecoveryMedicineCost();if((L.stocks.medicine||0)<cost)return actionResult('Insufficient Medicine',`Field-hospital treatment requires ${cost} Medicine. Current stock: ${L.stocks.medicine||0}.`,'warning',showSiegeIIRecovery);const q=siegeIIHealerCapacity();L.stocks.medicine-=cost;let treated=0;for(const o of siegeIIRecoveryOwners(true)){treated+=treatOwnerRecovery(o,Math.max(2,q),{clearBruises:true,stabilizeDays:6});recoveryRestoreOwner(o,clamp(.72+q*.05,.78,.97),1)}siegeIIRefreshShortages(L);const R=siegeIIRecoveryState();R.totalTreatments++;siegeIIRecoveryConsumeAction();const healer=siegeIIHealerCompanion();const text=`${recoveryMedicalLabel(q)} siege medical care uses ${cost} Medicine and treats ${treated} persistent injur${treated===1?'y':'ies'}${healer?` under ${healer.name}'s supervision`:''}.`;siegeIIRecoveryRecord('treatment',text,'good');save();actionResult('Field Hospital Treatment',text,'good',showSiegeIIRecovery)
}
function siegeIITrainingAction(){
 if(siegeIIRecoveryActionUsed())return showSiegeIIRecovery();const S=siegeIICombatState(),R=siegeIIRecoveryState();R.trainedAssault=S.assault;for(const o of siegeIIRecoveryOwners(true)){const g=o===state.guardian,ms=g?maxStamina():allyMaxStamina(o);o.stamina=Math.max(o.stamina,Math.round(ms*.82))}for(const m of partyMembers(true))SOSServices.companions.adjustTrust(m.id,1);siegeIIRecoveryConsumeAction();const text='The Guardian drills the active Party through breach response, target calls, and fallback signals. The next assault gains a modest coordination advantage.';siegeIIRecoveryRecord('training',text,'good');save();actionResult('Training Complete',text,'good',showSiegeIIRecovery)
}
function siegeIIPrepareAction(){
 if(siegeIIRecoveryActionUsed())return showSiegeIIRecovery();const S=siegeIICombatState(),R=siegeIIRecoveryState();R.preparedAssault=S.assault;siegeIIRestoreActive(.64,.9);siegeIIRecoveryConsumeAction();const text='The Player Party studies the current defensive position, routes, and fallback lanes. The next assault gains better opening control and a safer withdrawal plan.';siegeIIRecoveryRecord('preparation',text,'good');save();actionResult('Assault Preparation',text,'good',showSiegeIIRecovery)
}
function siegeIIDefenderRecoveryAction(){
 if(siegeIIRecoveryActionUsed())return showSiegeIIRecovery();const L=siegeIILogisticsState(),F=siegeIIForcesState();if(!(F.defenders.wounded||0))return actionResult('No Defender Treatment Needed','No strategic defenders are currently waiting in the wounded pool.','info',showSiegeIIRecovery);const q=siegeIIHealerCapacity(),cost=clamp(5+Math.floor((F.defenders.wounded||0)/18),5,12);if((L.stocks.medicine||0)<cost)return actionResult('Insufficient Medicine',`Supporting the defender hospitals requires ${cost} Medicine. Current stock: ${L.stocks.medicine||0}.`,'warning',showSiegeIIRecovery);L.stocks.medicine-=cost;const back=Math.min(F.defenders.wounded||0,Math.max(2,Math.floor((F.defenders.wounded||0)*(.12+q*.035))));F.defenders.wounded=Math.max(0,(F.defenders.wounded||0)-back);F.defenders.reserves=(F.defenders.reserves||0)+back;F.defenders.returned=(F.defenders.returned||0)+back;siegeIIRefreshShortages(L);const R=siegeIIRecoveryState();R.totalDefendersReturned+=back;siegeIIRecoveryConsumeAction();const text=`Medical staff concentrate on the city garrison. ${back} wounded defender${back===1?' returns':'s return'} to reserve duty at a cost of ${cost} Medicine.`;siegeIIRecoveryRecord('defender-recovery',text,back?'good':'info');save();actionResult('Defender Recovery',text,back?'good':'info',showSiegeIIRecovery)
}
function siegeIIRecoverySummaryHTML(){const S=siegeIIRecoveryStatus(),q=siegeIIHealerCapacity(),R=siegeIIRecoveryState(),used=siegeIIRecoveryActionUsed();return `<div class="siege2-recovery-summary"><div><b>${S.hpPct}%</b><small>Active Party HP</small></div><div><b>${S.staPct}%</b><small>Active Party stamina</small></div><div><b>${S.injuries}</b><small>Persistent injuries${S.serious?` • ${S.serious} serious`:''}</small></div><div><b>${recoveryMedicalLabel(q)}</b><small>Siege healer capacity</small></div></div><div class="notice ${S.serious?'warning':S.injuries?'':'success'} compact"><b>Downtime:</b> ${used?'The Guardian has already used this assault window.':'One recovery/downtime action is available before the next assault.'}${S.down?` • ${S.down} active combatant${S.down===1?' is':'s are'} down and should be treated/rested before fighting.`:''}</div>${recoveryStatusHTML(true)}`}
function siegeIIRecoveryHistoryHTML(){const R=siegeIIRecoveryState();return (R.history||[]).slice(0,7).map(x=>`<div class="siege2-history-row"><b>Assault ${x.assault}</b> — ${esc(x.kind)}<br><small>${esc(x.text)}</small></div>`).join('')||'<div class="muted compact">No Siege II downtime actions recorded yet.</div>'}
function showSiegeIIRecovery(){
 const S=siegeIICombatState(),L=siegeIILogisticsState(),F=siegeIIForcesState(),used=siegeIIRecoveryActionUsed(),cost=siegeIIRecoveryMedicineCost(),cond=siegeIIRecoveryStatus(),needsCare=cond.injuries||cond.hpPct<100||cond.staPct<100;overlay(`<h2>Siege Recovery & Downtime II</h2>${siegeIIRecoverySummaryHTML()}<div class="notice compact"><b>Field hospitals:</b> ${L.stocks.medicine||0} Medicine available • ${F.defenders.wounded||0} strategic defenders wounded.<br><small>Rest restores condition. Treatment reduces persistent injuries. Training/preparation trade recovery opportunity for combat readiness.</small></div><div class="choice-list siege2-recovery-actions"><button id="siege2Rest" ${used?'disabled':''}><b>Protected Rest</b><small>Strong HP/Stamina recovery; minor wound improvement.</small></button><button id="siege2Treat" ${(used||!needsCare)?'disabled':''}><b>Field Hospital Treatment — ${cost} Medicine</b><small>Best personal recovery; treats persistent Guardian/companion injuries.</small></button><button id="siege2Train" ${used?'disabled':''}><b>Train & Drill</b><small>Moderate stamina recovery and coordination bonus for Assault ${S.assault}.</small></button><button id="siege2Prepare" ${used?'disabled':''}><b>Prepare for Assault</b><small>Study the defensive line; improve opening control and withdrawal readiness.</small></button><button id="siege2DefRecover" ${(used||!(F.defenders.wounded||0))?'disabled':''}><b>Support Defender Recovery</b><small>Spend Medicine to return wounded city defenders to reserve duty.</small></button></div><h3>Recent Recovery Record</h3>${siegeIIRecoveryHistoryHTML()}<div class="dialog-footer"><button id="siege2RecoveryBack">Return to Command</button></div>`,true);$('#siege2Rest').onclick=siegeIIRestAction;$('#siege2Treat').onclick=siegeIITreatmentAction;$('#siege2Train').onclick=siegeIITrainingAction;$('#siege2Prepare').onclick=siegeIIPrepareAction;$('#siege2DefRecover').onclick=siegeIIDefenderRecoveryAction;$('#siege2RecoveryBack').onclick=()=>{closeOverlay();renderSiegeIICommand()}
}
// Apply one-assault training/preparation bonuses to the already-modernized assault generator.
const _siegeIIAssaultGroup1614=siegeIIAssaultGroup;
siegeIIAssaultGroup=function(){const gr=_siegeIIAssaultGroup1614(),S=siegeIICombatState(),R=siegeIIRecoveryState();gr.tactical=gr.tactical||{};if(R.trainedAssault===S.assault){gr.tactical.openingDamage=(gr.tactical.openingDamage||0)+2;gr.tactical.enemyAcc=(gr.tactical.enemyAcc||0)-1;gr.siegeIITraining=true}if(R.preparedAssault===S.assault){gr.tactical.openingDamage=(gr.tactical.openingDamage||0)+1;gr.tactical.retreat=(gr.tactical.retreat||0)+.06;gr.reinforcementChance=clamp((gr.reinforcementChance||0)-.03,0,.75);gr.siegeIIPrepared=true}return gr};
function siegeIIRecoveryAlertHTML(){const S=siegeIIRecoveryStatus(),used=siegeIIRecoveryActionUsed();return `<div class="notice ${S.serious?'warning':S.injuries?'':'success'} compact"><b>Recovery:</b> ${S.hpPct}% HP • ${S.staPct}% stamina • ${S.injuries} injur${S.injuries===1?'y':'ies'} • ${used?'downtime used':'downtime available'}</div>`}
// Final v1.6.14 command presentation, preserving Logistics II + Battlefield II actions as separate command resources.
renderSiegeIICommand=function(){
 if(!state)return renderMenu();const S=siegeIICombatState(),F=siegeIIForcesState(),B=siegeIIBattlefieldState(),L=siegeIILogisticsState(),R=siegeIIRecoveryState();checkLevel();siegeIISyncBreachIncidents(B);const ratio=S.pressure>=75?'Critical':S.pressure>=50?'Heavy':S.pressure>=25?'Rising':'Contained',D=siegeIIForceTotal(F.defenders,'defender'),A=siegeIIForceTotal(F.attackers,'attacker'),active=B.incidents.filter(x=>x.status==='active'),canBattle=B.commandActionAssault!==S.assault,canLog=L.commandActionAssault!==S.assault,canRecover=R.actionAssault!==S.assault;
 document.getElementById('app').innerHTML=`<div class="app-shell siege2-shell"><div class="titlebar"><div class="left">${esc(state.name)} • Level ${state.level} • ${fmt(state.gold)} gold</div><div>SIEGE MODE II</div><div class="right"><span>Recovery II</span><button id="menuBtn">Menu</button></div></div><div class="game-grid siege2-foundation-grid"><div class="sidebar"><div class="panel">${guardianPanel()}</div><div class="panel"><h3>Command</h3><div class="stat-row"><span>Next assault</span><b>${S.assault}</b></div><div class="stat-row"><span>Position</span><b>${esc(siegeIICurrentPosition(B).short)}</b></div><div class="stat-row"><span>Siege pressure</span><b>${S.pressure}/100 • ${ratio}</b></div><div class="stat-row"><span>Defender morale</span><b>${S.defenderMorale}/100</b></div><div class="stat-row"><span>Logistics readiness</span><b>${siegeIILogisticsReadiness(L)}%</b></div><div class="stat-row"><span>Defenders</span><b>${D}</b></div><div class="stat-row"><span>Besiegers</span><b>${A}</b></div><div class="choice-list"><button id="siege2Assault">Begin Assault ${S.assault}</button><button id="siege2Recovery">Recovery & Downtime${canRecover?' • ACTION AVAILABLE':''}</button><button id="siege2Logistics">Economy & Logistics${canLog?' • ORDER AVAILABLE':''}</button><button id="siege2Battlefield">Battlefield Situation${canBattle&&active.length?' • ACTION AVAILABLE':''}</button><button id="siege2Forces">Forces & Army Roster</button>${(state.guardian.classChoicePending||state.attributePoints||state.skillPoints)?'<button id="siegeIILevelUp">Level Up / Advancement</button>':''}<button id="siegeIIInventory">Inventory / Equipment</button><button id="siegeIIParty">Party / Roster</button><button id="siegeIIBriefing">Command Briefing</button></div></div></div><div class="panel siege2-command-panel"><h2>Siege Recovery & Downtime II</h2><div class="notice"><b>Surviving an assault no longer means the Player Party instantly resets for the next one.</b><br>Protected rest, field-hospital treatment, training, assault preparation, companion recovery, healer capacity, and strategic defender care now compete for the Guardian's limited between-assault downtime.</div>${siegeIIRecoverySummaryHTML()}${sieIIRecoveryAlertHTML()}${sieIILogisticsAlertHTML(L)}${sieIIBattlefieldAlertHTML(B)}<h3>Living Battlefield</h3>${sieIIBattlefieldSummaryHTML(B)}<h3>Persistent Armies</h3>${sieIIForceSummaryHTML(F)}<h3>Recent Battle Record</h3>${sieIIHistoryHTML(S)}<div class="notice compact"><b>Three separate command resources:</b> one Recovery/Downtime action, one Logistics order, and one Battlefield response can each be used before an assault. Choosing treatment/rest therefore does not erase your ability to issue supply orders or respond to a fire/breach.</div></div><div class="sidebar"><div class="panel"><h3>Modernization Status</h3><div class="stat-row"><span>Architecture</span><b>Ready</b></div><div class="stat-row"><span>Combat II</span><b>Active</b></div><div class="stat-row"><span>Forces II</span><b>Active</b></div><div class="stat-row"><span>Battlefield II</span><b>Active</b></div><div class="stat-row"><span>Logistics II</span><b>Active</b></div><div class="stat-row"><span>Recovery II</span><b>Active</b></div></div><div class="panel"><h3>Recovery Doctrine</h3><p class="compact">Medicine controls treatment quality and strategic wounded return. Rest is free but consumes the same downtime opportunity as treatment, training, or preparation.</p></div></div><div class="panel log-panel"><h3>Command Log</h3><div class="log">${state.log.slice(-50).map(x=>`<div class="log-line ${x.type}">${esc(x.msg)}</div>`).join('')}</div></div></div></div>`;
 $('#menuBtn').onclick=gameMenu;$('#siege2Assault').onclick=siegeIIStartAssault;$('#siege2Recovery').onclick=showSiegeIIRecovery;$('#siege2Logistics').onclick=showSiegeIILogistics;$('#siege2Battlefield').onclick=showSiegeIIBattlefield;$('#siege2Forces').onclick=showSiegeIIForces;if($('#siegeIILevelUp'))$('#siegeIILevelUp').onclick=showLevelUpPrompt;$('#siegeIIInventory').onclick=showInventory;$('#siegeIIParty').onclick=showParty;$('#siegeIIBriefing').onclick=showSiegeIIBriefing;save()
};
renderSiegeIIFoundation=renderSiegeIICommand;
